"""Real laboratory chemicals (with CAS numbers) and the products their reactions
make. Loaded by gen_substances.py. Values are realistic where it matters for
the behaviour (pKa, density, boiling point, heats of reaction); every reaction
emerges from the property channels, never from named pairs."""

WATERY = dict(specific_heat_j_kg_k=3800, melting_point_kelvin=260, boiling_point_kelvin=375, latent_heat_fusion_j_kg=300000,
              latent_heat_vaporization_j_kg=2100000, viscosity_pas=0.0012, pka_acidity=7.0, turbidity=0.05)
SOLID = dict(specific_heat_j_kg_k=900, melting_point_kelvin=900, boiling_point_kelvin=2000, latent_heat_fusion_j_kg=150000,
             latent_heat_vaporization_j_kg=1000000, viscosity_pas=0.01, pka_acidity=7.0, turbidity=1.0)
GAS = dict(specific_heat_j_kg_k=1000, melting_point_kelvin=150, boiling_point_kelvin=200, latent_heat_fusion_j_kg=50000,
           latent_heat_vaporization_j_kg=300000, viscosity_pas=0.0002, pka_acidity=7.0, turbidity=0.0)


def aq(name, formula, M, rho, color, **kw):
    d = dict(WATERY)
    d.update(name=name, formula=formula, molar_mass_kg_mol=M, density_kg_m3=rho, base_albedo_rgba=color)
    d.update(kw)
    return d


def solid(name, formula, M, rho, color, **kw):
    d = dict(SOLID)
    d.update(name=name, formula=formula, molar_mass_kg_mol=M, density_kg_m3=rho, base_albedo_rgba=color)
    d.update(kw)
    return d


def gas(name, formula, M, color, **kw):
    d = dict(GAS)
    d.update(name=name, formula=formula, molar_mass_kg_mol=M, density_kg_m3=1000, base_albedo_rgba=color)
    d.update(kw)
    return d


def organic(name, formula, M, rho, color, mp, bp, **kw):
    d = dict(specific_heat_j_kg_k=2400, latent_heat_fusion_j_kg=100000, latent_heat_vaporization_j_kg=700000, viscosity_pas=0.0008,
             pka_acidity=15.0, turbidity=0.02, melting_point_kelvin=mp, boiling_point_kelvin=bp)
    d.update(name=name, formula=formula, molar_mass_kg_mol=M, density_kg_m3=rho, base_albedo_rgba=color)
    d.update(kw)
    return d


